<script>
document.addEventListener('DOMContentLoaded',function(){
const clock=document.getElementById('dashboardLocalClock');
const renderClock=()=>{if(!clock)return;const now=new Date();clock.textContent=new Intl.DateTimeFormat('en-BD',{weekday:'short',day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:true,timeZone:'Asia/Dhaka'}).format(now)+' BST';};renderClock();window.setInterval(renderClock,1000);
const deck=document.querySelector('.dashboard-card-deck');const expand=document.getElementById('dashboardExpandMetrics');
if(deck&&expand){const cards=Array.from(deck.querySelectorAll('.dashboard-card'));const visibleCount=15;const apply=(showAll)=>{cards.forEach((card,index)=>{card.hidden=!showAll&&index>=visibleCount;});expand.setAttribute('aria-expanded',String(showAll));expand.querySelector('span').textContent=showAll?'Show fewer metrics':'Expand metrics';const count=cards.length-visibleCount;const badge=expand.querySelector('.dashboard-metric-count');if(badge)badge.textContent=showAll?'Collapse':'+'+Math.max(0,count);};apply(false);expand.addEventListener('click',()=>apply(expand.getAttribute('aria-expanded')!=='true'));}
const m=(id,c)=>{const e=document.getElementById(id);if(e&&window.Chart)new Chart(e,c)};
const v={!!$customerChartValues!!};
m('customerRingChart',{type:'doughnut',data:{labels:['Total','Active','Pending','Free','Temporary Disable','Inactive','Recent'],datasets:[{data:v}]},options:{responsive:true,maintainAspectRatio:false,cutout:'68%',plugins:{legend:{display:false}}}});
const n={!!$newConnectionValues!!};
m('newConnectionChart',{type:'bar',data:{labels:Object.keys(n),datasets:[{data:Object.values(n).map(x=>Number(x.total||0)),borderRadius:6}]},options:{responsive:true,maintainAspectRatio:false,scales:{y:{beginAtZero:true}},plugins:{legend:{display:false}}}});
m('revenueMixChart',{type:'doughnut',data:{labels:['Broadband','Hotspot'],datasets:[{data:{!!$revenueValues!!}}]},options:{responsive:true,maintainAspectRatio:false,cutout:'68%',plugins:{legend:{display:false}}}});
});
</script>
